data class MutexPair private constructor(val a: Int, val b: Int) {
    companion object {
        fun of(a: Int, b: Int): MutexPair = MutexPair(minOf(a, b), maxOf(a, b))
    }
}
typealias Mutex = Set<MutexPair>
data class GraphElement(val action: Int?, val pre: State, val add: State, val del: State)
data class GraphLevel(val elements: List<GraphElement>, val mutex: Mutex)
data class MemoKey(val level: Int, val goals: List<Int>)
class Extractor {
    val levels = mutableListOf<GraphLevel>()
    val memo = mutableSetOf<MemoKey>()
    var searched = 0
    var hits = 0
    var tried = 0
    fun extract(level: Int, goals: List<Int>): List<List<Int>>? {
        if (level == 0) return emptyList()
        val key = MemoKey(level, goals)
        if (key in memo) {
            hits++; return null
        }
        searched++
        val result = assign(level, goals, 0, emptyList())
        if (result == null) memo.add(key)
        return result
    }
    fun assign(j: Int, goals: List<Int>, position: Int, chosen: List<Int>): List<List<Int>>? {
        val level = levels[j - 1]
        var k = position
        while (k < goals.size && chosen.any {
            goals[k] in level.elements[it].add
        }) k++
        if (k == goals.size) {
            val previous = chosen.flatMap {
                level.elements[it].pre
            }.toSet().sorted()
            val plan = extract(j - 1, previous) ?: return null
            return plan + listOf(chosen.mapNotNull {
                level.elements[it].action
            }.sorted())
        }
        val goal = goals[k]
        val achievers = level.elements.indices.filter {
            goal in level.elements[it].add
        }.sortedWith(compareBy<Int> {
            if (level.elements[it].action == null) 0 else 1
        }.thenBy {
            level.elements[it].action ?: 0
        })
        for (x in achievers) if (chosen.all {
            x == it || MutexPair.of(x, it) !in level.mutex
        }) {
            tried++
            val plan = assign(j, goals, k + 1, chosen + x)
            if (plan != null) return plan
        }
        return null
    }
}
data class GraphResult(val search: SearchResult, val layers: List<List<Int>>, val records: List<String>, val hits: Int)
object GraphPlan {
    fun compatible(pre: State, mutex: Mutex): Boolean = pre.all {
        p -> pre.all {
            q -> p == q || MutexPair.of(p, q) !in mutex
        }
    }
    fun run(actions: List<Action>, initial: State, goals: State, limit: Int): GraphResult {
        val extractor = Extractor()
        var facts = initial
        var mutex: Mutex = emptySet()
        var previous: Pair<Int, Int>? = null
        val records = mutableListOf<String>()
        var answer = emptyList<List<Int>>()
        var status = "level limit"
        for (i in 0..limit) {
            records.add("fact level $i: facts=${facts.size} mutexes=${mutex.size}")
            val extract = facts.containsAll(goals) && compatible(goals, mutex)
            if (extract) {
                val before = extractor.searched
                val hits = extractor.hits
                val result = extractor.extract(i, goals.sorted())
                records.add("extract level $i: ${if (result == null) "fail" else "success"} searched=${extractor.searched - before} memo_hits=${extractor.hits - hits}")
                if (result != null) {
                    answer = result; status = "solved"; break
                }
            } else if (previous == Pair(facts.size, mutex.size)) {
                status = "unreachable"; break
            }
            if (i == limit) break
            previous = Pair(facts.size, mutex.size)
            val elements = actions.mapIndexedNotNull {
                index, action ->
                if (facts.containsAll(action.pre) && compatible(action.pre, mutex)) GraphElement(index, action.pre, action.add, action.del) else null
            }.toMutableList()
            val real = elements.size
            for (fact in facts.sorted()) elements.add(GraphElement(null, setOf(fact), setOf(fact), emptySet()))
            val actionMutex = mutableSetOf<MutexPair>()
            for (x in elements.indices) for (y in x + 1 until elements.size) {
                val a = elements[x]
                val b = elements[y]
                val interference = a.del.any {
                    it in b.pre || it in b.add
                } || b.del.any {
                    it in a.pre || it in a.add
                }
                val competing = a.pre.any {
                    p -> b.pre.any {
                        q -> p != q && MutexPair.of(p, q) in mutex
                    }
                }
                if (interference || competing) actionMutex.add(MutexPair.of(x, y))
            }
            records.add("action level $i: actions=$real noops=${facts.size} mutexes=${actionMutex.size}")
            val next = elements.flatMap {
                it.add
            }.toSet()
            val values = next.sorted()
            val nextMutex = mutableSetOf<MutexPair>()
            for (x in values.indices) for (y in x + 1 until values.size) {
                val p = values[x]
                val q = values[y]
                val impossible = elements.indices.filter {
                    p in elements[it].add
                }.all {
                    a ->
                    elements.indices.filter {
                        q in elements[it].add
                    }.all {
                        b -> a != b && MutexPair.of(a, b) in actionMutex
                    }
                }
                if (impossible) nextMutex.add(MutexPair.of(p, q))
            }
            extractor.levels.add(GraphLevel(elements, actionMutex))
            facts = next; mutex = nextMutex
        }
        return GraphResult(SearchResult(status, answer.flatten(), extractor.searched, extractor.tried), answer, records, extractor.hits)
    }
}

typealias State = Set<Int>
data class Action(val source: Int, val name: String, val args: List<String>, val cost: Int,
val pre: State, val neg: State, val add: State, val del: State) {
    val text: String get() = Atom(name, args).text
}
data class Grounding(val facts: List<Atom>, val actions: List<Action>, val initial: State, val goals: State,
val unreachable: List<Atom>, val stats: Array<IntArray>, val fluent: Set<String>, val staticCount: Int)
data class GroundCandidate(val source: Int, val args: List<String>, val pre: MutableSet<Atom> = mutableSetOf(),
val neg: MutableSet<Atom> = mutableSetOf(), val add: MutableSet<Atom> = mutableSetOf(), val del: MutableSet<Atom> = mutableSetOf())
fun lexCompare(a: List<Int>, b: List<Int>): Int {
    for (i in 0 until minOf(a.size, b.size)) if (a[i] != b[i]) return a[i].compareTo(b[i])
    return a.size.compareTo(b.size)
}
object Grounder {
    fun subtype(domain: Domain, type: String, expected: String): Boolean {
        var current = type
        while (true) {
            if (current == expected) return true
            current = domain.parents[current] ?: return false
        }
    }
    fun fluents(domain: Domain): Set<String> = domain.actions.flatMap {
        a -> a.effects.map {
            it.atom.predicate
        }
    }.toSet()
    fun ground(domain: Domain, problem: Problem): Grounding {
        val fluent = fluents(domain)
        val initial = problem.initial.toSet()
        val stats = Array(domain.actions.size) {
            IntArray(3)
        }
        val candidates = mutableListOf<GroundCandidate>()
        for ((source, action) in domain.actions.withIndex()) {
            val choices = action.parameters.map {
                p -> problem.objects.filter {
                    subtype(domain, it.type, p.type)
                }.map {
                    it.name
                }
            }
            val all = mutableListOf<List<String>>()
            val current = mutableListOf<String>()
            fun combinations(i: Int) {
                if (i == choices.size) {
                    all.add(current.toList()); return
                }
                for (obj in choices[i]) {
                    current.add(obj); combinations(i + 1); current.removeAt(current.lastIndex)
                }
            }
            combinations(0)
            stats[source][0] = all.size
            for (args in all) {
                val values = action.parameters.map {
                    it.name
                }.zip(args).toMap()
                val candidate = GroundCandidate(source, args)
                var valid = true
                for (literal in action.pre) {
                    val atom = literal.atom.replace(values)
                    if (atom.predicate == "=" || atom.predicate !in fluent) {
                        val truth = if (atom.predicate == "=") atom.terms[0] == atom.terms[1] else atom in initial
                        if (truth == literal.negative) {
                            valid = false; break
                        }
                    } else if (literal.negative) candidate.neg.add(atom) else candidate.pre.add(atom)
                }
                if (!valid) continue
                for (literal in action.effects) {
                    val atom = literal.atom.replace(values)
                    if (literal.negative) candidate.del.add(atom) else candidate.add.add(atom)
                }
                candidate.del.removeAll(candidate.add)
                stats[source][1]++
                candidates.add(candidate)
            }
        }
        val reachable = initial.filter {
            it.predicate in fluent
        }.toMutableSet()
        val kept = mutableSetOf<Int>()
        while (true) {
            val before = kept.size
            for ((i, candidate) in candidates.withIndex()) if (reachable.containsAll(candidate.pre)) {
                kept.add(i); reachable.addAll(candidate.add)
            }
            if (kept.size == before) break
        }
        val predicates = domain.predicates.withIndex().associate {
            it.value.name to it.index
        }
        val objects = problem.objects.withIndex().associate {
            it.value.name to it.index
        }
        val facts = reachable.sortedWith(Comparator {
            a, b ->
            val order = predicates.getValue(a.predicate).compareTo(predicates.getValue(b.predicate))
            if (order != 0) order else lexCompare(a.terms.map {
                objects.getValue(it)
            }, b.terms.map {
                objects.getValue(it)
            })
        })
        val numbering = facts.withIndex().associate {
            it.value to it.index
        }
        fun numbers(atoms: Set<Atom>): State = atoms.mapNotNull {
            numbering[it]
        }.toSet()
        val actions = kept.sorted().map {
            i ->
            val candidate = candidates[i]
            val action = domain.actions[candidate.source]
            stats[candidate.source][2]++
            Action(candidate.source, action.name, candidate.args, action.cost, numbers(candidate.pre), numbers(candidate.neg), numbers(candidate.add), numbers(candidate.del))
        }
        val goals = mutableSetOf<Int>()
        val unreachable = mutableListOf<Atom>()
        for (atom in problem.goals) {
            val i = numbering[atom]
            if (i != null) goals.add(i) else if (atom.predicate in fluent || atom !in initial) unreachable.add(atom)
        }
        return Grounding(facts, actions, numbers(initial), goals, unreachable, stats, fluent, problem.initial.count {
            it.predicate !in fluent
        })
    }
}

data class Relaxed(val value: Long, val plan: List<Int>, val helpful: List<Int>)
object Heuristics {
    const val INFINITY = 1_000_000_000_000L
    fun aggregate(values: List<Long>, maximum: Boolean): Long =
    if (values.any {
        it >= INFINITY
    }) INFINITY else if (maximum) values.maxOrNull() ?: 0L else values.sum()
    fun costs(g: Grounding, state: State, maximum: Boolean): LongArray {
        val costs = LongArray(g.facts.size) {
            INFINITY
        }
        for (fact in state) costs[fact] = 0
        while (true) {
            var changed = false
            for (action in g.actions) {
                val previous = aggregate(action.pre.map {
                    costs[it]
                }, maximum)
                if (previous >= INFINITY) continue
                val value = previous + action.cost
                for (fact in action.add) if (value < costs[fact]) {
                    costs[fact] = value; changed = true
                }
            }
            if (!changed) return costs
        }
    }
    fun relaxed(g: Grounding, state: State): Relaxed {
        val costs = costs(g, state, false)
        if (g.goals.any {
            costs[it] >= INFINITY
        }) return Relaxed(INFINITY, emptyList(), emptyList())
        fun achiever(fact: Int): Int = g.actions.indices.filter {
            i ->
            fact in g.actions[i].add && g.actions[i].pre.all {
                costs[it] < INFINITY
            }
        }.minWithOrNull(compareBy<Int> {
            i -> g.actions[i].cost + g.actions[i].pre.sumOf {
                costs[it]
            }
        }.thenBy {
            it
        })!!
        val chosen = mutableSetOf<Int>()
        val pending = (g.goals - state).sorted().toMutableList()
        while (pending.isNotEmpty()) {
            val action = achiever(pending.removeAt(pending.lastIndex))
            if (chosen.add(action)) pending.addAll((g.actions[action].pre - state).sorted())
        }
        val plan = chosen.sorted()
        return Relaxed(plan.sumOf {
            g.actions[it].cost.toLong()
        }, plan, plan.filter {
            Search.applicable(g.actions[it], state)
        })
    }
    fun landmarks(g: Grounding, state: State): State? {
        val factLevel = IntArray(g.facts.size) {
            Int.MAX_VALUE
        }
        val actionLevel = IntArray(g.actions.size) {
            Int.MAX_VALUE
        }
        for (fact in state) factLevel[fact] = 0
        var k = 0
        while (true) {
            var added = false
            for ((i, action) in g.actions.withIndex()) if (actionLevel[i] == Int.MAX_VALUE && action.pre.all {
                factLevel[it] <= k
            }) {
                actionLevel[i] = k
                for (fact in action.add) if (factLevel[fact] == Int.MAX_VALUE) {
                    factLevel[fact] = k + 1; added = true
                }
            }
            if (!added) break
            k++
        }
        if (g.goals.any {
            factLevel[it] == Int.MAX_VALUE
        }) return null
        val landmarks = (g.goals - state).toMutableSet()
        while (true) {
            val before = landmarks.size
            for (fact in landmarks.sorted()) {
                val achievers = g.actions.indices.filter {
                    actionLevel[it] != Int.MAX_VALUE && actionLevel[it] + 1 == factLevel[fact] && fact in g.actions[it].add
                }
                val candidates = g.actions[achievers[0]].pre.toMutableSet()
                for (i in achievers.drop(1)) candidates.retainAll(g.actions[i].pre)
                for (candidate in (candidates - state).sorted()) if (candidate !in landmarks) {
                    val reachable = state.toMutableSet()
                    while (true) {
                        val old = reachable.size
                        for (action in g.actions) if (candidate !in action.add && reachable.containsAll(action.pre)) reachable.addAll(action.add)
                        if (old == reachable.size) break
                    }
                    if (!reachable.containsAll(g.goals)) landmarks.add(candidate)
                }
            }
            if (before == landmarks.size) return landmarks
        }
    }
    fun value(g: Grounding, state: State, name: String): Long = when (name) {
        "none" -> 0L
        "goalcount" -> (g.goals - state).size.toLong()
        "hmax", "hadd" -> {
            val maximum = name == "hmax"; val c = costs(g, state, maximum); aggregate(g.goals.map {
                c[it]
            }, maximum)
        }
        "ff" -> relaxed(g, state).value
        else -> landmarks(g, state)?.size?.toLong() ?: INFINITY
    }
    fun values(g: Grounding, state: State): List<Long> = listOf("goalcount", "hmax", "hadd", "ff", "lmcount").map {
        value(g, state, it)
    }
}

import java.io.File
fun arguments(domain: Domain, args: List<String>, expected: List<String>, table: Map<String, String>, noun: String): String? {
    if (args.size != expected.size) return "expected ${expected.size} arguments, got ${args.size}"
    for ((i, name) in args.withIndex()) {
        val actual = table[name] ?: return "unknown $noun $name"
        if (!Grounder.subtype(domain, actual, expected[i])) return "argument ${i + 1} ($name) is not of type ${expected[i]}"
    }
    return null
}
fun atomError(domain: Domain, atom: Atom, table: Map<String, String>, noun: String, equality: Boolean): String? {
    val types = if (equality && atom.predicate == "=") listOf("object", "object")
    else domain.predicates.firstOrNull {
        it.name == atom.predicate
    }?.types ?: return "unknown predicate ${atom.predicate}"
    return arguments(domain, atom.terms, types, table, noun)
}
fun validateDomain(domain: Domain) {
    val actions = mutableListOf<Schema>()
    for (action in domain.actions) {
        val table = action.parameters.associate {
            it.name to it.type
        }
        var error = action.parameters.firstOrNull {
            it.type !in domain.typeOrder
        }?.let {
            "unknown type ${it.type}"
        }
        if (error == null) for (literal in action.pre + action.effects) {
            val reason = atomError(domain, literal.atom, table, "variable", true)
            if (reason != null) {
                error = "${literal.atom.text}: $reason"; break
            }
        }
        if (error != null) domain.diagnostics.add("error: action ${action.name}: $error") else actions.add(action)
    }
    domain.actions = actions
    for (predicate in domain.predicates) if (domain.actions.none {
        a -> (a.pre + a.effects).any {
            it.atom.predicate == predicate.name
        }
    }) {
        domain.diagnostics.add("warning: predicate ${predicate.name} is not used by any action")
    }
}
fun validateProblem(domain: Domain, problem: Problem) {
    val table = problem.objects.associate {
        it.name to it.type
    }
    for (side in 0..1) {
        val original = if (side == 0) problem.initial else problem.goals
        val seen = mutableSetOf<Atom>()
        val kept = mutableListOf<Atom>()
        for (atom in original) {
            val error = atomError(domain, atom, table, "object", false) ?: if (atom in seen) "duplicate" else null
            if (error != null) problem.diagnostics.add("warning: ${if (side == 0) "init" else "goal"} ${atom.text}: $error")
            else {
                seen.add(atom); kept.add(atom)
            }
        }
        if (side == 0) problem.initial = kept else problem.goals = kept
    }
}
fun listed(heading: String, values: List<String>): String = heading + " " + if (values.isEmpty()) "-" else values.joinToString(" ")
fun numbers(values: State): String = if (values.isEmpty()) "-" else values.sorted().joinToString(",")
fun hText(value: Long): String = if (value >= Heuristics.INFINITY) "inf" else value.toString()
fun hValues(values: List<Long>): String = listOf("goalcount", "hmax", "hadd", "ff", "lmcount").zip(values).joinToString(" ") {
    "${it.first}=${hText(it.second)}"
}
fun cost(g: Grounding, plan: List<Int>): Long = plan.sumOf {
    g.actions[it].cost.toLong()
}
fun domainReport(domain: Domain): List<String> {
    val lines = (listOf("== domain ${domain.name} ==") + domain.diagnostics).toMutableList()
    for (type in domain.typeOrder) {
        val chain = mutableListOf(type)
        var current = type
        while (true) {
            current = domain.parents[current] ?: break; chain.add(current)
        }
        lines.add("type " + chain.joinToString(" < "))
    }
    val fluent = Grounder.fluents(domain)
    for (p in domain.predicates) lines.add("predicate ${p.name}/${p.types.size} ${if (p.name in fluent) "fluent" else "static"}")
    for (a in domain.actions) lines.add("action ${a.name}/${a.parameters.size} cost=${a.cost} pre=${a.pre.size} add=${a.effects.count { !it.negative }} del=${a.effects.count { it.negative }}")
    return lines
}
fun groundingReport(domain: Domain, problem: Problem, g: Grounding): List<String> {
    val lines = (listOf("", "== problem ${problem.name} ==") + problem.diagnostics + "objects: ${problem.objects.size}").toMutableList()
    for (type in domain.typeOrder) lines.add(listed("  $type:", problem.objects.filter {
        Grounder.subtype(domain, it.type, type)
    }.map {
        it.name
    }))
    lines.add("static facts: ${g.staticCount}")
    for ((i, a) in domain.actions.withIndex()) lines.add("schema ${a.name}: assignments=${g.stats[i][0]} candidates=${g.stats[i][1]} reachable=${g.stats[i][2]}")
    lines.add("candidates: ${g.stats.sumOf { it[1] }} reachable: ${g.actions.size}")
    lines.add("facts: ${g.facts.size} init: ${g.initial.size} goals: ${g.goals.size}")
    for (atom in g.unreachable) lines.add("unreachable goal: ${atom.text}")
    lines.add(listed("facts by predicate:", domain.predicates.filter {
        it.name in g.fluent
    }.map {
        p -> "${p.name}=${g.facts.count { it.predicate == p.name }}"
    }))
    lines.add("facts:")
    for ((i, atom) in g.facts.withIndex()) lines.add("  $i ${atom.text}")
    lines.add("actions:")
    for ((i, a) in g.actions.withIndex()) lines.add("  $i ${a.text} cost=${a.cost} pre=${numbers(a.pre)} neg=${numbers(a.neg)} add=${numbers(a.add)} del=${numbers(a.del)}")
    return lines
}
data class Validation(val status: String, val messages: List<String>, val correct: Int) {
    val verdict: String get() = if (status == "valid") "valid ${messages[0]}" else "$status: ${messages[0]}"
}
fun validateSteps(domain: Domain, problem: Problem, steps: List<Atom>): Validation {
    val world = problem.initial.toMutableSet()
    var cost = 0L
    val table = problem.objects.associate {
        it.name to it.type
    }
    for ((k, step) in steps.withIndex()) {
        val action = domain.actions.firstOrNull {
            it.name == step.predicate
        }
        ?: return Validation("invalid", listOf("step ${k + 1} ${step.text}: unknown action ${step.predicate}"), k)
        val error = arguments(domain, step.terms, action.parameters.map {
            it.type
        }, table, "object")
        if (error != null) return Validation("invalid", listOf("step ${k + 1} ${step.text}: $error"), k)
        val values = action.parameters.map {
            it.name
        }.zip(step.terms).toMap()
        for (original in action.pre) {
            val literal = original.replace(values)
            val atom = literal.atom
            val truth = if (atom.predicate == "=") atom.terms[0] == atom.terms[1] else atom in world
            if (truth == literal.negative) return Validation("invalid", listOf("step ${k + 1} ${step.text}: precondition ${literal.text} is false"), k)
        }
        for (literal in action.effects) if (literal.negative) world.remove(literal.atom.replace(values))
        for (literal in action.effects) if (!literal.negative) world.add(literal.atom.replace(values))
        cost += action.cost
    }
    val missing = problem.goals.filter {
        it !in world
    }.map {
        "unsatisfied goal ${it.text}"
    }
    return if (missing.isEmpty()) Validation("valid", listOf("length=${steps.size} cost=$cost"), steps.size) else Validation("goal not reached", missing, steps.size)
}
fun steps(g: Grounding, plan: List<Int>): List<Atom> = plan.map {
    Atom(g.actions[it].name, g.actions[it].args)
}
fun mapSteps(g: Grounding, steps: List<Atom>): List<Int> = steps.map {
    step -> g.actions.indexOfFirst {
        it.name == step.predicate && it.args == step.terms
    }
}
fun interfere(a: Action, b: Action): Boolean = a.del.any {
    it in b.pre || it in b.add
} || b.del.any {
    it in a.pre || it in a.add
} || a.add.any {
    it in b.neg
} || b.add.any {
    it in a.neg
}
fun parallel(g: Grounding, plan: List<Int>): List<List<Int>> {
    val levels = mutableListOf<Int>()
    for ((j, action) in plan.withIndex()) {
        var level = 0
        for (i in 0 until j) {
            val a = g.actions[plan[i]]
            val b = g.actions[action]
            if (a.add.any {
                it in b.pre
            } || a.del.any {
                it in b.neg
            } || interfere(a, b)) level = maxOf(level, levels[i])
        }
        levels.add(level + 1)
    }
    val layers = List(levels.maxOrNull() ?: 0) {
        mutableListOf<Int>()
    }
    for ((i, action) in plan.withIndex()) layers[levels[i] - 1].add(action)
    return layers
}
fun parallelVerdict(g: Grounding, layers: List<List<Int>>): String {
    var state = g.initial
    for ((k, layer) in layers.withIndex()) {
        val bad = layer.indices.any {
            i -> layer.drop(i + 1).any {
                interfere(g.actions[layer[i]], g.actions[it])
            }
        }
        if (bad || layer.any {
            !Search.applicable(g.actions[it], state)
        }) return "invalid at layer ${k + 1}"
        state = (state - layer.flatMap {
            g.actions[it].del
        }.toSet()) + layer.flatMap {
            g.actions[it].add
        }
    }
    return if (state.containsAll(g.goals)) "valid" else "goal not reached"
}
fun improve(g: Grounding, input: List<Int>): List<Int> {
    var plan = input
    var i = 0
    while (i < plan.size) {
        var state = g.initial
        for (action in plan.take(i)) state = Search.apply(g.actions[action], state)
        val next = plan.take(i).toMutableList()
        for (action in plan.drop(i + 1)) if (Search.applicable(g.actions[action], state)) {
            state = Search.apply(g.actions[action], state); next.add(action)
        }
        if (state.containsAll(g.goals)) plan = next else i++
    }
    return plan
}
data class Transformed(val actions: List<Action>, val initial: State, val complements: Int)
fun transformed(g: Grounding): Transformed {
    val negatives = g.actions.flatMap {
        it.neg
    }.toSet().sorted()
    val complements = negatives.withIndex().associate {
        it.value to g.facts.size + it.index
    }
    val initial = g.initial + negatives.filter {
        it !in g.initial
    }.map {
        complements.getValue(it)
    }
    val actions = g.actions.map {
        a -> a.copy(pre = a.pre + a.neg.map {
            complements.getValue(it)
        }, add = a.add + a.del.mapNotNull {
            complements[it]
        }, del = a.del + a.add.mapNotNull {
            complements[it]
        })
    }
    return Transformed(actions, initial, negatives.size)
}
data class Params(var budget: Int = 0, var weight: Int = 0, var limit: Int = 0,
val runs: MutableList<Pair<String, String>> = mutableListOf(), var repair: Pair<String, String> = Pair("", "")) {
    companion object {
        fun read(): Params {
            val p = Params()
            for (line in File("input/params.txt").readLines()) if (line.isNotEmpty() && !line.startsWith('#')) {
                val a = line.split(' ')
                when (a[0]) {
                    "budget" -> p.budget = a[1].toInt(); "weight" -> p.weight = a[1].toInt(); "graphplan" -> p.limit = a[1].toInt(); "run" -> p.runs.add(Pair(a[1], a[2])); else -> p.repair = Pair(a[1], a[2])
                }
            }
            return p
        }
    }
}
data class Candidate(val problem: String, val label: String, val steps: MutableList<Atom> = mutableListOf())
fun readCandidates(): List<Candidate> {
    val result = mutableListOf<Candidate>()
    for (line in File("input/candidates.txt").readLines()) if (line.isNotEmpty() && !line.startsWith('#')) {
        if (line.startsWith("plan ")) {
            val a = line.split(' '); result.add(Candidate(a[1], a[2]))
        }
        else if (line != "end") {
            val a = line.substring(1, line.length - 1).split(' '); result.last().steps.add(Atom(a[0], a.drop(1)))
        }
    }
    return result
}
data class PlanBlock(val lines: List<String>, val validation: List<String>, val valid: Boolean)
fun planBlock(domain: Domain, problem: Problem, g: Grounding, plan: List<Int>, tag: String, landmarks: State, seen: MutableList<Pair<List<Int>, String>>): PlanBlock {
    val first = seen.firstOrNull {
        it.first == plan
    }
    val same = first?.let {
        " (same as ${it.second})"
    } ?: ""
    if (first == null) seen.add(Pair(plan, tag))
    val lines = mutableListOf("plan: length=${plan.size} cost=${cost(g, plan)}$same")
    for ((k, action) in plan.withIndex()) lines.add("  ${k + 1} ${g.actions[action].text}")
    lines.add(listed("schemas:", domain.actions.mapIndexedNotNull {
        i, action ->
        val count = plan.count {
            g.actions[it].source == i
        }; if (count == 0) null else "${action.name}=$count"
    }))
    val layers = parallel(g, plan)
    lines.add("parallel: layers=${layers.size}")
    for ((k, layer) in layers.withIndex()) lines.add(listed("  ${k + 1}:", layer.map {
        g.actions[it].text
    }))
    val improved = improve(g, plan)
    lines.add("improved: length=${improved.size} cost=${cost(g, improved)} removed=${plan.size - improved.size}")
    if (improved.size < plan.size) {
        for ((k, action) in improved.withIndex()) lines.add("  ${k + 1} ${g.actions[action].text}")
    }
    var state = g.initial
    val reached = mutableSetOf<Int>()
    for (action in plan) {
        state = Search.apply(g.actions[action], state); reached.addAll(state.intersect(landmarks))
    }
    lines.add("landmarks reached: ${reached.size}/${landmarks.size}")
    for (fact in (landmarks - reached).sorted()) lines.add("  missed ${g.facts[fact].text}")
    val original = validateSteps(domain, problem, steps(g, plan))
    val checked = validateSteps(domain, problem, steps(g, improved))
    return PlanBlock(lines, listOf("$tag: ${original.verdict}", "  parallel: ${parallelVerdict(g, layers)}", "  improved: ${checked.verdict}"), original.status == "valid")
}
fun profile(g: Grounding, plan: List<Int>, tag: String): List<String> {
    val lines = mutableListOf("-- profile ($tag) --")
    var state = g.initial
    var remaining = cost(g, plan)
    val over = LongArray(5)
    for (k in 0..plan.size) {
        val values = Heuristics.values(g, state)
        for (i in 0 until 5) if (values[i] > remaining) over[i]++
        lines.add("  $k: h*=$remaining ${hValues(values)}")
        if (k < plan.size) {
            state = Search.apply(g.actions[plan[k]], state); remaining -= g.actions[plan[k]].cost
        }
    }
    lines.add("overestimates: ${hValues(over.toList())}")
    lines.add("-- causal links ($tag) --")
    val suppliers = IntArray(g.facts.size)
    for ((k, action) in plan.withIndex()) {
        lines.add(listed("  ${k + 1} ${g.actions[action].text}:", g.actions[action].pre.sorted().map {
            "${g.facts[it].text}<-${suppliers[it]}"
        }))
        for (fact in g.actions[action].add) suppliers[fact] = k + 1
    }
    lines.add(listed("  goal:", g.goals.sorted().map {
        "${g.facts[it].text}<-${suppliers[it]}"
    }))
    return lines
}
fun resultLine(result: SearchResult, unreachable: Boolean): String = if (unreachable) "result: FAIL (unreachable goal)"
else if (result.status == "solved") "result: solved expanded=${result.expanded} generated=${result.generated}"
else "result: FAIL (${result.status}) expanded=${result.expanded} generated=${result.generated}"
fun write(name: String, lines: List<String>) {
    File("output").mkdirs()
    File("output/$name").writeText(if (lines.isEmpty()) "" else lines.joinToString("\n") + "\n")
}
fun main() {
    val domain = PDDLParser.domain()
    validateDomain(domain)
    val problems = PDDLParser.problems()
    for (problem in problems) validateProblem(domain, problem)
    val params = Params.read()
    val grounds = problems.map {
        Grounder.ground(domain, it)
    }
    val tags = params.runs.map {
        "${it.first} ${it.second}"
    } + "graphplan"
    val groundingLines = domainReport(domain).toMutableList()
    val plans = mutableListOf<String>()
    val graphLines = mutableListOf<String>()
    val validation = mutableListOf<String>()
    val comparison = mutableListOf("problem,algorithm,heuristic,length,cost,expanded,generated")
    val problemSummary = mutableListOf<String>()
    val tagStats = Array(tags.size) {
        IntArray(4)
    }
    val bests = mutableListOf<Long?>()
    var analyzed = 0
    var validPlans = 0
    for ((index, problem) in problems.withIndex()) {
        val g = grounds[index]
        val unreachable = g.unreachable.isNotEmpty()
        groundingLines.addAll(groundingReport(domain, problem, g))
        val heading = "== problem ${problem.name} =="
        plans.add(heading); validation.add(heading); graphLines.add(heading)
        var landmarks: State = emptySet()
        if (unreachable) plans.add("initial h: unreachable goal")
        else {
            plans.add("initial h: ${hValues(Heuristics.values(g, g.initial))}")
            landmarks = Heuristics.landmarks(g, g.initial) ?: emptySet()
            plans.add("landmarks: ${landmarks.size}")
            for (fact in landmarks.sorted()) plans.add("  ${g.facts[fact].text}")
            val relaxed = Heuristics.relaxed(g, g.initial)
            plans.add("relaxed plan: length=${relaxed.plan.size} cost=${hText(relaxed.value)}")
            for (action in relaxed.plan) plans.add("  ${g.actions[action].text}")
            plans.add(listed("helpful:", relaxed.helpful.map {
                g.actions[it].text
            }))
        }
        val results = params.runs.map {
            (algorithm, heuristic) -> if (unreachable) SearchResult("unreachable goal") else Search.run(g, g.initial, algorithm, heuristic, params.budget, params.weight)
        }.toMutableList()
        if (unreachable) {
            graphLines.add("result: FAIL (unreachable goal)"); results.add(SearchResult("unreachable goal"))
        }
        else {
            val transformedGraph = transformed(g)
            val graph = GraphPlan.run(transformedGraph.actions, transformedGraph.initial, g.goals, params.limit)
            graphLines.add("complementary facts: ${transformedGraph.complements}")
            graphLines.addAll(graph.records)
            if (graph.search.status == "solved") {
                graphLines.add("result: solved levels=${graph.layers.size} length=${graph.search.plan.size} cost=${cost(g, graph.search.plan)} searched=${graph.search.expanded} memo_hits=${graph.hits} tried=${graph.search.generated}")
                for ((k, layer) in graph.layers.withIndex()) graphLines.add(listed("layer ${k + 1}:", layer.map {
                    g.actions[it].text
                }))
            } else graphLines.add("result: FAIL (${graph.search.status}) searched=${graph.search.expanded} memo_hits=${graph.hits} tried=${graph.search.generated}")
            results.add(graph.search)
        }
        graphLines.add("")
        val best = results.filter {
            it.status == "solved"
        }.minOfOrNull {
            cost(g, it.plan)
        }
        bests.add(best)
        val proof = params.runs.indices.firstOrNull {
            i ->
            val pair = params.runs[i]
            (pair == Pair("ucs", "none") || pair == Pair("astar", "hmax")) && results[i].status == "solved"
        }
        val optimal = if (proof != null) cost(g, results[proof].plan).toString()
        else if (results.any {
            it.status in listOf("unreachable goal", "dead end", "exhausted", "unreachable")
        }) "none" else "unknown"
        problemSummary.add("${problem.name}: solved=${results.count { it.status == "solved" }}/${results.size} best=${best ?: "-"} optimal=$optimal")
        val seen = mutableListOf<Pair<List<Int>, String>>()
        for ((i, result) in results.withIndex()) {
            plans.add("-- ${tags[i]} --"); plans.add(resultLine(result, unreachable))
            tagStats[i][2] += result.expanded; tagStats[i][3] += result.generated
            val pair = params.runs.getOrNull(i) ?: Pair("graphplan", "none")
            var length = "-"
            var costText = "-"
            if (result.status == "solved") {
                tagStats[i][0]++
                if (cost(g, result.plan) == best) tagStats[i][1]++
                val block = planBlock(domain, problem, g, result.plan, tags[i], landmarks, seen)
                plans.addAll(block.lines); validation.addAll(block.validation); analyzed++
                if (block.valid) validPlans++
                length = result.plan.size.toString(); costText = cost(g, result.plan).toString()
            }
            comparison.add("${problem.name},${pair.first},${pair.second},$length,$costText,${result.expanded},${result.generated}")
        }
        if (proof != null) plans.addAll(profile(g, results[proof].plan, tags[proof]))
        plans.add(""); validation.add("")
    }
    plans.add("== summary =="); plans.addAll(problemSummary)
    for ((i, tag) in tags.withIndex()) plans.add("$tag: solved=${tagStats[i][0]} best=${tagStats[i][1]} expanded=${tagStats[i][2]} generated=${tagStats[i][3]}")
    validation.add("== candidates ==")
    val candidates = readCandidates()
    var validCandidates = 0
    for ((k, candidate) in candidates.withIndex()) {
        val index = problems.indexOfFirst {
            it.name == candidate.problem
        }
        val problem = problems[index]
        val g = grounds[index]
        val checked = validateSteps(domain, problem, candidate.steps)
        if (checked.status == "valid") {
            validCandidates++
            validation.add("candidate ${k + 1} ${problem.name} ${candidate.label}: ${checked.verdict}")
            val mapped = mapSteps(g, candidate.steps)
            val improved = improve(g, mapped)
            validation.add("  improved: length=${improved.size} cost=${cost(g, improved)} removed=${mapped.size - improved.size} best known=${bests[index] ?: "-"}")
        } else {
            validation.add("candidate ${k + 1} ${problem.name} ${candidate.label}: ${checked.status}")
            validation.addAll(checked.messages.map {
                "  $it"
            })
            if (g.unreachable.isNotEmpty()) {
                validation.add("  repair: FAIL (unreachable goal)"); continue
            }
            val mapped = mapSteps(g, candidate.steps.take(checked.correct))
            var state = g.initial
            for (action in mapped) state = Search.apply(g.actions[action], state)
            val repair = Search.run(g, state, params.repair.first, params.repair.second, params.budget, params.weight)
            if (repair.status != "solved") validation.add("  repair: FAIL (${repair.status})")
            else {
                val repairedPlan = mapped + repair.plan
                val repaired = validateSteps(domain, problem, steps(g, repairedPlan))
                validation.add("  repair: kept=${checked.correct} added=${repair.plan.size} ${repaired.verdict}")
                for ((j, action) in repairedPlan.withIndex()) validation.add("    ${j + 1} ${g.actions[action].text}")
            }
        }
    }
    validation.addAll(listOf("", "== summary ==", "plans: $analyzed valid: $validPlans", "candidates: ${candidates.size} valid: $validCandidates"))
    write("grounding.txt", groundingLines); write("plans.txt", plans); write("graphplan.txt", graphLines)
    write("validation.txt", validation); write("comparison.csv", comparison)
}

import java.io.File
sealed interface Expr {
    data class Word(val text: String) : Expr
    data class Group(val values: List<Expr>) : Expr
    val word: String get() = (this as Word).text
    val list: List<Expr> get() = (this as Group).values
}
data class Atom(val predicate: String, val terms: List<String>) {
    constructor(expr: Expr) : this(expr.list[0].word, expr.list.drop(1).map {
        it.word
    })
    val text: String get() = (listOf(predicate) + terms).joinToString(" ", "(", ")")
    fun replace(values: Map<String, String>): Atom = Atom(predicate, terms.map {
        values.getValue(it)
    })
}
data class Literal(val atom: Atom, val negative: Boolean = false) {
    val text: String get() = if (negative) "(not ${atom.text})" else atom.text
    fun replace(values: Map<String, String>): Literal = Literal(atom.replace(values), negative)
}
data class Typed(val name: String, val type: String)
data class Schema(val name: String, var parameters: List<Typed> = emptyList(), var pre: List<Literal> = emptyList(),
val effects: MutableList<Literal> = mutableListOf(), var cost: Int = 1)
data class Predicate(val name: String, val types: List<String>)
class Domain(val name: String) {
    val typeOrder = mutableListOf("object")
    val parents = mutableMapOf<String, String>()
    val predicates = mutableListOf<Predicate>()
    var actions = mutableListOf<Schema>()
    val diagnostics = mutableListOf<String>()
}
class Problem(val name: String) {
    var objects: List<Typed> = emptyList()
    var initial: List<Atom> = emptyList()
    var goals: List<Atom> = emptyList()
    val diagnostics = mutableListOf<String>()
}
object PDDLParser {
    fun expressions(path: String): List<Expr> {
        val tokens = mutableListOf<String>()
        for (line in File(path).readLines()) {
            val word = StringBuilder()
            fun flush() {
                if (word.isNotEmpty()) {
                    tokens.add(word.toString()); word.clear()
                }
            }
            for (c in line.takeWhile {
                it != ';'
            }) {
                if (c in "() ") {
                    flush(); if (c != ' ') tokens.add(c.toString())
                } else word.append(c)
            }
            flush()
        }
        var i = 0
        fun read(): Expr {
            val token = tokens[i++]
            if (token != "(") return Expr.Word(token)
            val children = mutableListOf<Expr>()
            while (tokens[i] != ")") children.add(read())
            i++
            return Expr.Group(children)
        }
        val result = mutableListOf<Expr>()
        while (i < tokens.size) result.add(read())
        return result
    }
    fun typed(words: List<Expr>): List<Typed> {
        val result = mutableListOf<Typed>()
        val pending = mutableListOf<String>()
        var i = 0
        while (i < words.size) {
            if (words[i].word == "-") {
                i++
                result.addAll(pending.map {
                    Typed(it, words[i].word)
                })
                pending.clear()
            } else pending.add(words[i].word)
            i++
        }
        return result + pending.map {
            Typed(it, "object")
        }
    }
    fun conjunction(expr: Expr): List<Expr> = if (expr.list[0].word == "and") expr.list.drop(1) else listOf(expr)
    fun literal(expr: Expr): Literal = if (expr.list[0].word == "not") Literal(Atom(expr.list[1]), true) else Literal(Atom(expr))
    fun domain(): Domain {
        val a = expressions("input/domain.txt")[0].list
        val domain = Domain(a[1].list[1].word)
        for (expr in a.drop(2)) {
            val s = expr.list
            when (s[0].word) {
                ":types" -> {
                    for (word in s.drop(1)) if (word.word != "-" && word.word !in domain.typeOrder) {
                        domain.typeOrder.add(word.word)
                        if (word.word != "object") domain.parents[word.word] = "object"
                    }
                    for ((name, type) in typed(s.drop(1))) domain.parents[name] = type
                }
                ":predicates" -> for (value in s.drop(1)) domain.predicates.add(Predicate(value.list[0].word, typed(value.list.drop(1)).map {
                    it.type
                }))
                ":action" -> {
                    val action = Schema(s[1].word)
                    var i = 2
                    while (i < s.size) {
                        when (s[i].word) {
                            ":parameters" -> action.parameters = typed(s[i + 1].list)
                            ":precondition" -> action.pre = conjunction(s[i + 1]).map(::literal)
                            else -> for (effect in conjunction(s[i + 1])) {
                                if (effect.list[0].word == "increase") action.cost = effect.list[2].word.toInt()
                                else action.effects.add(literal(effect))
                            }
                        }
                        i += 2
                    }
                    domain.actions.add(action)
                }
            }
        }
        return domain
    }
    fun problems(): List<Problem> = expressions("input/problems.txt").map {
        expr ->
        val a = expr.list
        val problem = Problem(a[1].list[1].word)
        for (section in a.drop(2)) {
            val s = section.list
            when (s[0].word) {
                ":objects" -> problem.objects = typed(s.drop(1))
                ":init" -> problem.initial = s.drop(1).map(::Atom)
                ":goal" -> problem.goals = conjunction(s[1]).map(::Atom)
            }
        }
        problem
    }
}

import java.util.PriorityQueue
data class SearchResult(var status: String, var plan: List<Int> = emptyList(), var expanded: Int = 0, var generated: Int = 0)
data class SearchNode(val state: State, val g: Long, val depth: Int, val parent: Int?, val action: Int?)
data class SearchKey(val f: Long, val h: Long, val serial: Int)
object Search {
    fun applicable(action: Action, state: State): Boolean = state.containsAll(action.pre) && action.neg.none {
        it in state
    }
    fun apply(action: Action, state: State): State = (state - action.del) + action.add
    fun run(g: Grounding, start: State, algorithm: String, heuristic: String, budget: Int, weight: Int): SearchResult {
        if (algorithm == "ehc") return ehc(g, start, heuristic, budget)
        val result = SearchResult("exhausted")
        val initialH = Heuristics.value(g, start, heuristic)
        if (initialH >= Heuristics.INFINITY) {
            result.status = "dead end"; return result
        }
        val nodes = mutableListOf(SearchNode(start, 0, 0, null, null))
        val frontier = PriorityQueue(compareBy<SearchKey> {
            it.f
        }.thenBy {
            it.h
        }.thenBy {
            it.serial
        })
        val table = mutableMapOf(start to 0L)
        fun key(cost: Long, depth: Int, h: Long, serial: Int): SearchKey {
            val f = when (algorithm) {
                "bfs" -> depth.toLong(); "ucs" -> cost; "gbfs" -> h; "astar" -> cost + h; else -> cost + weight * h
            }
            return SearchKey(f, h, serial)
        }
        frontier.add(key(0, 0, initialH, 0))
        while (frontier.isNotEmpty()) {
            val index = frontier.remove().serial
            val node = nodes[index]
            val state = node.state
            if (algorithm in listOf("ucs", "astar", "wastar") && node.g > table.getValue(state)) continue
            if (state.containsAll(g.goals)) {
                result.status = "solved"
                var current = index
                val plan = mutableListOf<Int>()
                while (nodes[current].parent != null) {
                    plan.add(nodes[current].action!!); current = nodes[current].parent!!
                }
                result.plan = plan.reversed()
                return result
            }
            if (result.expanded == budget) {
                result.status = "budget"; return result
            }
            result.expanded++
            for ((a, action) in g.actions.withIndex()) if (applicable(action, state)) {
                result.generated++
                val next = apply(action, state)
                val cost = node.g + action.cost
                val old = table[next]
                if (old != null && (algorithm in listOf("bfs", "gbfs") || old <= cost)) continue
                table[next] = cost
                val h = Heuristics.value(g, next, heuristic)
                if (h >= Heuristics.INFINITY) continue
                val serial = nodes.size
                nodes.add(SearchNode(next, cost, node.depth + 1, index, a))
                frontier.add(key(cost, node.depth + 1, h, serial))
            }
        }
        return result
    }
    fun ehc(g: Grounding, start: State, heuristic: String, budget: Int): SearchResult {
        val result = SearchResult("stuck")
        var current = start
        var hc = Heuristics.value(g, start, heuristic)
        if (hc >= Heuristics.INFINITY) {
            result.status = "dead end"; return result
        }
        while (true) {
            if (current.containsAll(g.goals)) {
                result.status = "solved"; return result
            }
            val queue = ArrayDeque<Pair<State, List<Int>>>()
            queue.addLast(Pair(current, emptyList()))
            val visited = mutableSetOf(current)
            var improvement: Triple<State, Long, List<Int>>? = null
            while (queue.isNotEmpty() && improvement == null) {
                val (state, path) = queue.removeFirst()
                if (result.expanded == budget) {
                    result.status = "budget"; return result
                }
                result.expanded++
                for (action in Heuristics.relaxed(g, state).helpful) {
                    result.generated++
                    val next = apply(g.actions[action], state)
                    if (!visited.add(next)) continue
                    val h = Heuristics.value(g, next, heuristic)
                    if (h >= Heuristics.INFINITY) continue
                    val nextPath = path + action
                    if (h < hc) {
                        improvement = Triple(next, h, nextPath); break
                    }
                    queue.addLast(Pair(next, nextPath))
                }
            }
            val found = improvement ?: return result
            current = found.first; hc = found.second; result.plan = result.plan + found.third
        }
    }
}
